def is_valid_markdown_link(s):
    import re
    m = re.fullmatch(r'\[([^\]]+)\]\((\S+)\)', s)
    if not m:
        return False
    url = m.group(2)
    return url.startswith('http://') or url.startswith('https://')

def minutes_since_midnight(time_str):
    h, m = time_str.split(':')
    return int(h)*60 + int(m)

def matches_wildcard(s, pattern):
    m, n = len(s), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif pattern[j-1] == '?' or s[i-1] == pattern[j-1]:
                dp[i][j] = dp[i-1][j-1]
    return dp[m][n]

def split_on_multiple_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for c in s:
        if c in delim_set:
            if current:
                tokens.append("".join(current))
                current = []
        else:
            current.append(c)
    if current:
        tokens.append("".join(current))
    return tokens

def integer_nth_root(n, k):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def longest_run_length(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def is_balanced_curly(s):
    depth = 0
    for c in s:
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

def count_palindromic_substrings(s):
    n = len(s)
    count = 0
    def expand(l, r):
        nonlocal count
        while l >= 0 and r < n and s[l] == s[r]:
            count += 1
            l -= 1
            r += 1
    for i in range(n):
        expand(i, i)
        expand(i, i+1)
    return count

def oxford_join_no_oxford(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f" and {items[-1]}"

def last_day_of_month(year, month):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    return (year, month, lengths[month-1])

def convert_base_to_base(s, from_base, to_base):
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    value = 0
    for ch in s.lower():
        value = value * from_base + digits.index(ch)
    if value == 0:
        return '0'
    result = []
    while value > 0:
        result.append(digits[value % to_base])
        value //= to_base
    return ''.join(reversed(result))

def find_anagram_matches(words, target):
    key = sorted(target.lower())
    return [w for w in words if sorted(w.lower()) == key]

def meets_min_digit_count_policy(s):
    if any(c.isspace() for c in s):
        return False
    if not (6 <= len(s) <= 20):
        return False
    return sum(c.isdigit() for c in s) >= 2

def max_product_of_two(lst):
    s = sorted(lst)
    return max(s[-1] * s[-2], s[0] * s[1])

def second_largest_with_duplicates(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[1]

def capitalize_first_word_each_line(text):
    lines = text.split("\n")
    out = []
    for line in lines:
        if line == "":
            out.append(line)
            continue
        lowered = line.lower()
        fixed = lowered
        for i, ch in enumerate(lowered):
            if ch.isalpha():
                fixed = lowered[:i] + ch.upper() + lowered[i + 1:]
                break
        out.append(fixed)
    return "\n".join(out)

def camel_case_join(words):
    if not words:
        return ""
    return words[0].lower() + ''.join(w.capitalize() for w in words[1:])

def count_distinct_substrings_length_k(s, k):
    if k <= 0 or k > len(s):
        return 0
    return len(set(s[i:i + k] for i in range(len(s) - k + 1)))

def is_leap_year_from_string(year_str):
    year = int(year_str)
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

def sum_of_prime_factors(n):
    total = 0
    x = n
    p = 2
    while p * p <= x:
        if x % p == 0:
            total += p
            while x % p == 0:
                x //= p
        p += 1
    if x > 1:
        total += x
    return total

def render_row_mixed(cells, widths, aligns):
    parts = []
    for c, w, a in zip(cells, widths, aligns):
        if a == 'l':
            parts.append(c.ljust(w))
        elif a == 'r':
            parts.append(c.rjust(w))
        else:
            parts.append(c.center(w))
    return " ".join(parts)

def is_prime_power(n):
    if n < 2:
        return False
    temp = n
    d = 2
    prime_found = None
    while d * d <= temp:
        if temp % d == 0:
            prime_found = d
            while temp % d == 0:
                temp //= d
            break
        d += 1
    if prime_found is None:
        return True
    return temp == 1
